echo '' | base64 -d > /tmp/kret.pl; docker cp /tmp/kret.pl koha-test:/tmp/kret.pl; docker exec koha-test chmod 644 /tmp/kret.pl
docker exec koha-test koha-shell kohadent -c "perl /tmp/kret.pl" 2>&1 | grep -v "^\s*'" | tail -3
echo '' | base64 -d > /tmp/kt4.php; docker cp /tmp/kt4.php filenest-app:/tmp/x.php
docker exec -u www-data -w /var/www/html filenest-app php -r "require 'vendor/autoload.php'; \$app = require 'bootstrap/app.php'; \$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); require '/tmp/x.php';" 2>&1 | head -6
docker exec filenest-app rm -f /tmp/x.php; rm -f /tmp/kt4.php /tmp/kret.pl
